def amax(x, axis=None, keepdims=False):
    if axis is None:
        return ivy.max(x)
    if isinstance(axis, int):
        axis = [axis]
    for i in range(len(axis)):
        if axis[i] < 0:
            axis[i] += x.ndim
    for i in axis:
        if i < 0 or i >= x.ndim:
            raise ValueError("axis {} is out of range [-{}:{}]".format(i, 0, x.ndim))
    return ivy.max(x, axis=axis, keepdims=keepdims)


